after.hourglass/gaps.py:
"""Finding the stretches of a day that nobody covers."""

from typing import Iterable, List

from hourglass.parsing import format_span
from hourglass.models import Span
from hourglass.merging import merge_spans
from hourglass.errors import OutsideHoursError

def _outside(span: Span, opening: Span) -> bool:
    return (
        span.start < opening.start
        or span.end > opening.end
    )

def _check(spans: List[Span], opening: Span) -> None:
    for span in spans:
        if _outside(span, opening):
            raise OutsideHoursError(format_span(span))

def _uncovered(
    spans: List[Span], opening: Span
) -> List[Span]:
    merged = merge_spans(spans)
    lefts = [opening.start] + [part.end for part in merged]
    rights = [part.start for part in merged] + [opening.end]
    pairs = zip(lefts, rights)
    return [
        Span(low, high) for low, high in pairs if low < high
    ]

def _label(span: Span) -> str:
    return f"gap {format_span(span)} ({span.minutes} min)"

# ---
def find_gaps(
    worked: Iterable[Span], opening: Span
) -> List[str]:
    """One label per uncovered stretch of opening hours."""
    spans = list(worked)
    _check(spans, opening)
    found = _uncovered(spans, opening)
    return [_label(item) for item in found]
